                items = []
                child = index + 1
                want_keys = index < key_limit
                while child < index + size:
                    items.append(vals[child])
                    if want_keys:
                        keys[child] is None  # keys already recorded per child
                    child += nodes[child][2]
                value = items
                vals[index] = value
                if want_keys:
                    keys[index] = ("a", tuple(keys[c] for c in _child_ids(index, size, nodes)))
            elif kind == K_STRUCT:
                names = data
                record = {}
                child = index + 1
                want_keys = index < key_limit
                paired = []
                for name in names:
                    record[name] = vals[child]
                    if want_keys:
                        paired.append((name, keys[child]))
                    child += nodes[child][2]
                vals[index] = record
                if want_keys:
                    keys[index] = ("s", tuple(paired))
            else:  # pragma: no cover - defensive
                raise TestError("unknown node kind")
        layout = self.layout
        values = [vals[root] for root in layout.param_roots]
        identities = tuple((name, keys[root])
                           for name, root in zip(layout.param_names, layout.param_roots))
        result = None if layout.result_root is None else vals[layout.result_root]
        flag = None if layout.flag_root is None else vals[layout.flag_root]
        return values, identities, result, flag


def _child_ids(index, size, nodes):
    ids = []
    child = index + 1
    end = index + size
    while child < end:
        ids.append(child)
        child += nodes[child][2]
    return ids
