"""Typed model elements: named types, module signatures, and expressions.

Types mirror the declaration vocabulary of the campaign language and are built
once per campaign by :func:`parse_types`.  Aliases are transparent for values
and layouts but keep their declaration name.

Expression nodes form the predicate AST.  Each node knows how to evaluate
itself against a lexical assignment dictionary, which keeps scoping (``all``
binding shadowing) local to the node that introduces it.
"""

from typing import Any, Dict, List, Optional, Tuple

import eywa.regex as regex


# --------------------------------------------------------------------------- #
# Types
# --------------------------------------------------------------------------- #

class Type(object):
    """An Eywa type for a parameter to a function."""

    __slots__ = ()

    @staticmethod
    def inner(type):
        """Look past any type aliases to get the inner type."""
        while isinstance(type, Alias):
            type = type.type
        return type


class Void(Type):
    """A void type representing no value."""

    __slots__ = ()


class Bool(Type):
    """A boolean type representing true or false."""

    __slots__ = ()


class Char(Type):
    """A character type representing a single Latin-1 character."""

    __slots__ = ()


class Int(Type):
    """An unsigned integer type of a given bit width."""

    __slots__ = ("size", "bytes", "limit")

    def __init__(self, size: int = 32):
        self.size = size                      # declared bits, 1..64
        self.bytes = _int_bytes(size)         # harness byte width
        self.limit = 1 << size                # exclusive value bound


def _int_bytes(bits: int) -> int:
    for width in (1, 2, 4, 8):
        if bits <= width * 8:
            return width
    return 8


class String(Type):
    """A bounded Latin-1 C string type."""

    __slots__ = ("maxsize", "char_type")

    def __init__(self, maxsize: int = 6):
        if maxsize < 0:
            raise Exception("invalid string type")
        self.maxsize = maxsize
        self.char_type = Char()


class Enum(Type):
    """An enumeration type representing a choice of values."""

    __slots__ = ("name", "values")

    def __init__(self, name: str, values: List[str]):
        self.name = name
        self.values = tuple(values)


class Array(Type):
    """An ordered fixed-length list of a given element type."""

    __slots__ = ("element_type", "maxsize")

    def __init__(self, element_type: Type, maxsize: int):
        self.maxsize = maxsize
        self.element_type = element_type


class Struct(Type):
    """An object with exactly the declared fields, in declaration order."""

    __slots__ = ("name", "fields", "names")

    def __init__(self, name: str, fields: Dict[str, Type]):
        self.name = name
        self.fields = fields                  # ordered field_name -> Type
        self.names = tuple(fields)


class Alias(Type):
    """A transparent value/layout alias that retains its declaration name."""

    __slots__ = ("name", "type", "description")

    def __init__(self, name: str, type: Type, description=None):
        self.name = name
        self.type = type

# --------------------------------------------------------------------------- #
# Expressions
# --------------------------------------------------------------------------- #

class Expr(object):
    """A simple expression class; subclasses evaluate against an assignment.

    The operator overloads keep the toolkit's fluent predicate-building API:
    ``params["n"].lt(Const(Int(8), 3)) & params["ok"]`` and the JSON decoder
    below produce the same node classes.
    """

    __slots__ = ("type",)

    def __hash__(self):                    # identity, not structural equality
        return id(self)

    def eval(self, assignment: Dict[str, Any]) -> Any:
        raise NotImplementedError(type(self).__name__)

    @staticmethod
    def convert(other):
        """Ensure the given object can be used as an expression."""
        if isinstance(other, Expr):
            return other
        if isinstance(other, Parameter):
            return Var(other.type, other.name)
        raise Exception("invalid expression: %r" % (other,))

    def __and__(self, other):
        return Logical(Bool(), "and", self, Expr.convert(other))

    def __or__(self, other):
        return Logical(Bool(), "or", self, Expr.convert(other))

    def implies(self, other):
        return Logical(Bool(), "implies", self, Expr.convert(other))

    def __invert__(self):
        return Not(Bool(), self)

    def __eq__(self, other):
        return Compare(Bool(), "eq", self, Expr.convert(other))

    def __ne__(self, other):
        return Compare(Bool(), "ne", self, Expr.convert(other))

    def __lt__(self, other):
        return Compare(Bool(), "lt", self, Expr.convert(other))

    def __le__(self, other):
        return Compare(Bool(), "le", self, Expr.convert(other))

    def __gt__(self, other):
        return Compare(Bool(), "gt", self, Expr.convert(other))

    def __ge__(self, other):
        return Compare(Bool(), "ge", self, Expr.convert(other))

    def __add__(self, other):
        return Arithmetic(self.type, "add", self, Expr.convert(other),
                          1 << Type.inner(self.type).size)

    def __sub__(self, other):
        return Arithmetic(self.type, "sub", self, Expr.convert(other),
                          1 << Type.inner(self.type).size)

    def get_field(self, field: str):
        record = Type.inner(self.type)
        return Field(record.fields[field], self, field)

    def matches(self, pattern):
        if isinstance(pattern, str):
            pattern = regex.compile(pattern)
        return Match(Bool(), self, pattern)

    def forall(self, binding: str, body):
        element = Type.inner(self.type).element_type
        if isinstance(body, bool):
            body = Const(Bool(), body)

